# A higher-order function wrapper (Decorator pattern):
def announce(fn):
    def wrapper(x):
        print("[LOG] Running with input:", x)
        return fn(x)
    return wrapper

def square(n: int) -> int:
    return n * n

logged_square = announce(square)
result = logged_square(6)
print("Computed result:", result)

