# Production Service Layer + Automated Unit Test Pattern:
def calculate_invoice(unit_price: int, quantity: int, vip: bool) -> dict:
    if quantity <= 0:
        return {"ok": False, "total": 0}
    subtotal = unit_price * quantity
    discount = int(subtotal * 0.10) if vip else 0
    return {"ok": True, "total": subtotal - discount}

# Automated test assertions (like pytest):
res1 = calculate_invoice(100, 2, True)
res2 = calculate_invoice(100, 0, False)
print("VIP Invoice:", res1)
print("Zero Qty Guard:", res2)

