def audit_password(pw: str) -> str:
    if len(pw) < 10:
        return "WEAK: Must be at least 10 characters"
    if "!" not in pw and "#" not in pw and "@" not in pw:
        return "WEAK: Add a special symbol (!, #, @)"
    return "STRONG: Meets defensive policy"

print("Test 1:", audit_password("12345"))
print("Test 2:", audit_password("SecurePython#2026"))

