# O(n) Two-Sum existence check with a Set
def has_pair_with_sum(nums, target):
    seen = set()
    for x in nums:
        if (target - x) in seen:
            return True
        seen.add(x)
    return False
print("Pair summing to 9 exists?", has_pair_with_sum([2, 7, 11, 15], 9))

